const fs = require('fs');
const path = require('path');

// Read and parse the CSV file
const csvPath = '/data/samples/user_activity_sample.csv';
const csvContent = fs.readFileSync(csvPath, 'utf-8');
const lines = csvContent.trim().split('\n');
const headers = lines[0].split(',');

console.log('Headers:', headers);
console.log('Processing', lines.length - 1, 'data rows...');

// Convert CSV to JSON format expected by Moose API
const events = [];
for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',');
    if (values.length === headers.length) {
        const event = {
            eventId: values[0],
            eventTs: values[1], // ISO timestamp format
            userId: values[2],
            action: values[3],
            durationMs: parseFloat(values[4]) || 0 // Default null/NaN to 0 as requested
        };
        events.push(event);
    }
}

console.log('Converted', events.length, 'events');
console.log('Sample event:', JSON.stringify(events[0], null, 2));

// Send data to Moose ingestion API
const sendBatch = async (batch) => {
    try {
        const response = await fetch('http://localhost:4000/ingest/UserActivityEvent', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify(batch)
        });

        if (!response.ok) {
            const errorText = await response.text();
            throw new Error(`HTTP ${response.status}: ${errorText}`);
        }

        const result = await response.text();
        console.log('✅ Batch sent successfully:', result);
        return true;
    } catch (error) {
        console.error('❌ Failed to send batch:', error.message);
        return false;
    }
};

// Send data in batches
const sendAllEvents = async () => {
    console.log('\nSending events to Moose ingestion API...');

    // Send all events in one batch for simplicity
    const success = await sendBatch(events);

    if (success) {
        console.log(`\n🎉 Successfully loaded ${events.length} events into ClickHouse!`);
    } else {
        console.log('\n❌ Failed to load data');
        process.exit(1);
    }
};

sendAllEvents();

